        props.gravityWell || (routePointer ? { ...ROUTE_WELL_OVERRIDE } : false);
    const pinned = props.pinned ?? false;
    const pinnedDrift = props.pinnedDrift ?? false;
    const warpAutoRelease = props.warpAutoRelease ?? false;

