                if (reducedMotionNow()) return;
                const local = toLocal(event);
                if (!local) return;
                if (props.pointerReactive !== false)
                    ripples.push({ ...local, start: -1 });
                if (warpOnClick) warpFieldTo(field, local.x, local.y);
