            attributes: true,
            attributeFilter: ["class"],
        });

        handle = useCanvas2D({
            canvas: canvasRef,
            respectReducedMotion: true,
            setup: () => ({
                render(ctx, now) {
                    const dpr = Math.min(window.devicePixelRatio || 1, 2);
                    const w = canvas.width ? canvas.width / dpr : BASE_WIDTH;
                    const h = canvas.height ? canvas.height / dpr : 720;
