            if (holdTimer !== undefined) clearTimeout(holdTimer);
            paletteObserver?.disconnect();
            for (const [type, listener] of listeners)
                target.removeEventListener(type, listener);
            pointerField.dispose();
            handle?.dispose();
            handle = null;
        };
    });

