        releaseWell(): void {
            if (!field.well) return;
            field.well.target = 0;
            handle?.wake();
        },
        warpSettled: () => fieldWarpSettled(field),
        pinNode(idx: number): void {
            field.pinnedIndex = idx;
            if (field.pinnedDrift) field.pinnedDrift.nextAt = -1;
            handle?.wake();
        },
        rendererStatus: readonly(rendererStatus),
    };
}

