        const tx = pd.anchorX + (rng() * 2 - 1) * f * field.w;
        const ty = pd.anchorY + (rng() * 2 - 1) * f * field.h;
        pd.toX = Math.max(0.04 * field.w, Math.min(0.96 * field.w, tx));
        pd.toY = Math.max(0.04 * field.h, Math.min(0.96 * field.h, ty));
