    const rendererStatus = shallowRef<RendererStatus>(pendingRenderer("webgpu"));
    const simulation = createBlobSimulation({
        color,
        rimColor,
        paletteStops,
        satelliteColors,
        mood,
        pointer,
        satellites,
        config,
        getReducedMotion: () => canvasHandle?.reducedMotion ?? false,
        wake: () => canvasHandle?.wake(),
    });

