        label: "[Aurora] image bind-group-0",
        entries: [
            { binding: 0, visibility: SHADER_STAGE_FRAGMENT, buffer: { type: "uniform" } },
            {
                binding: 1,
                visibility: SHADER_STAGE_FRAGMENT,
                texture: { sampleType: "float", viewDimension: "2d" },
            },
            {
                binding: 2,
                visibility: SHADER_STAGE_FRAGMENT,
                sampler: { type: "filtering" },
            },
        ],
    });

