            frameHooks?.resize(sizeBacking(canvas, options.dprPolicy));
            frameHooks?.frame(0);
        } catch {
            // A consumer-`frame` JS throw is not a GPU validation signal — the validation
            // scope owns the pipeline verdict. Swallow so the pop is clean.
        }
